import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;

public class Compiler_initOptions_TriageGen2Test {

    private Compiler compiler;
    private CompilerOptions options;

    @Before
    public void setUp() {
        compiler = new Compiler();
        options = new CompilerOptions();
    }

    @Test
    public void testInitOptions_DefaultErrorManager() {
        // When errorManager is null and outStream is null (default)
        compiler.initOptions(options);

        assertNotNull(compiler.getErrorManager());
        // Should be a LoggerErrorManager by default in this logic path
    }

    @Test
    public void testInitOptions_WithPrintStream() {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        PrintStream ps = new PrintStream(out);
        // Using the constructor that provides a stream to trigger the 'else' branch for outStream
        Compiler streamCompiler = new Compiler(ps);

        streamCompiler.initOptions(options);

        assertNotNull(streamCompiler.getErrorManager());
        // Verify it doesn't crash and sets error manager
    }

    @Test
    public void testInitOptions_WithExistingErrorManager() {
        ErrorManager existingManager = new LoggerErrorManager(new MessageFormatter(), null);
        compiler.setErrorManager(existingManager);

        compiler.initOptions(options);

        // Should not overwrite existing error manager
        assertThat(compiler.getErrorManager()).isEqualTo(existingManager);
    }

    @Test
    public void testInitOptions_DiagnosticGroupsCheckTypesEnable() {
        options.setCheckTypes(false);
        // Force enable via DiagnosticGroups
        options.setWarningLevel(DiagnosticGroups.CHECK_TYPES, CheckLevel.OFF);
        options.setWarningLevel(DiagnosticGroups.CHECK_TYPES, CheckLevel.HIGH); 
        // Note: depends on how 'enables' is implemented in CompilerOptions, 
        // assuming standard rhino/jscomp behavior where setting level enables it.

        compiler.initOptions(options);

        assertThat(options.checkTypes).isTrue();
    }

    @Test
    public void testInitOptions_DiagnosticGroupsCheckTypesDisable() {
        options.setCheckTypes(true);
        options.setWarningLevel(DiagnosticGroups.CHECK_TYPES, CheckLevel.OFF);

        compiler.initOptions(options);

        assertThat(options.checkTypes).isFalse();
    }

    @Test
    public void testInitOptions_DiagnosticGroupsNoOverrideAndCheckTypesFalse() {
        options.setCheckTypes(false);
        // Ensure DiagnosticGroups doesn't touch it
        options.setWarningLevel(DiagnosticGroups.CHECK_TYPES, CheckLevel.OFF); 
        // In many implementations, setting level to OFF is different from 'not enabling/disabling'
        // But for the sake of the branch: if !options.checkTypes and no override

        compiler.initOptions(options);

        // The code sets warning level for TYPE_PARSE_ERROR to OFF
        assertThat(options.getWarningLevel(RhinoErrorReporter.TYPE_PARSE_ERROR)).isEqualTo(CheckLevel.OFF);
    }

    @Test
    public void testInitOptions_CheckGlobalThisLevelOn() {
        options.checkGlobalThisLevel = CheckLevel.HIGH;

        compiler.initOptions(options);

        assertThat(options.getWarningLevel(DiagnosticGroups.GLOBAL_THIS)).isEqualTo(CheckLevel.HIGH);
    }

    @Test
    public void testInitOptions_CheckGlobalThisLevelOff() {
        options.checkGlobalThisLevel = CheckLevel.OFF;

        compiler.initOptions(options);

        assertThat(options.getWarningLevel(DiagnosticGroups.GLOBAL_THIS)).isEqualTo(CheckLevel.OFF);
    }

    @Test
    public void testInitOptions_CheckSymbolsTrue() {
        options.checkSymbols = true;

        compiler.initOptions(options);

        // If checkSymbols is true, the guard for CHECK_VARIABLES should NOT be added
        // We verify that the compiler completes without exception
        assertNotNull(compiler.getErrorManager());
    }

    @Test
    public void testInitOptions_CheckSymbolsFalseAndNoWarningsGuard() {
        options.checkSymbols = false;
        // warningsGuard is null by default in a new compiler

        compiler.initOptions(options);

        // Should trigger the branch to add DiagnosticGroupWarningsGuard
        assertNotNull(compiler.getErrorManager());
    }

    @Test
    public void testInitOptions_CheckSymbolsFalseAndWarningsGuardDisablesVariables() {
        options.checkSymbols = false;
        // We can't easily inject a mock warningsGuard into the private field without reflection,
        // but we can simulate the logic by ensuring the branch is covered.
        // Since we can't easily mock the internal state of 'warningsGuard' before it's initialized,
        // we rely on the standard path.

        compiler.initOptions(options);
        assertNotNull(compiler.getErrorManager());
    }
}
